def generate(rng: random.Random, n: int) -> list[dict]:
    n_lit = n // 2
    n_nar = n - n_lit

    lit_pool = list(_LITERATURE)
    rng.shuffle(lit_pool)
    lit_rows = [
        sentence(CATEGORY, "literature", text, f"Source: {source}")
        for text, source in lit_pool[:n_lit]
    ]

    nar_pool = list(_NARRATION)
    rng.shuffle(nar_pool)
    nar_rows = [
        sentence(CATEGORY, "narration", text, "YouTube-style explainer content")
        for text in nar_pool[:n_nar]
    ]

    combined = lit_rows + nar_rows
    combined.sort(key=lambda r: (r["subcategory"], r["text"]))
    return combined
